import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { beforeEach, describe, expect, it } from 'vitest'
import { asUser, createTestDb, createUser, type TestDb } from './testDb'
import { SEEDED_COURSES } from '@/configs/courses'

/*
 * supabase/seeds/<course>.sql (generated by `npm run db:course-seed`): run against the real migrations,
 * each installs its course, published, for the teacher named in the definition.
 */

describe.each(SEEDED_COURSES.map((c) => [c.title, c] as const))('%s seed', (_title, course) => {
    const SEED = readFileSync(
        join(__dirname, '..', '..', 'supabase', 'seeds', `${course.id.replace(/-/g, '_')}.sql`),
        'utf8',
    )
    let db: TestDb

    beforeEach(async () => {
        db = await createTestDb()
    })

    it('refuses to run until the teacher’s account exists', async () => {
        await expect(db.exec(SEED)).rejects.toThrow(/No teacher account has the email/)
        await createUser(db, course.ownerEmail) // still a student
        await expect(db.exec(SEED)).rejects.toThrow(/No teacher account has the email/)
        expect((await db.query(`select 1 from public.courses`)).rows).toHaveLength(0)
    })

    it('adds every unit, lesson, quiz and boss battle, published and authored by the teacher', async () => {
        const teacher = await createUser(db, course.ownerEmail.toUpperCase(), 'teacher')
        await db.exec(SEED)

        const courses = await db.query<{ id: string; status: string; join_code: string; created_by: string }>(
            `select c.id, c.status, c.join_code, c.created_by from public.courses c
             join public.course_teachers t on t.course_id = c.id and t.teacher_id = $1`,
            [teacher],
        )
        expect(courses.rows).toHaveLength(1)
        const [row] = courses.rows
        expect(row).toMatchObject({ status: 'published', join_code: course.joinCode, created_by: teacher })

        const modules = await db.query<{ title: string }>(
            `select title from public.modules where course_id = $1 order by position`,
            [row.id],
        )
        expect(modules.rows.map((m) => m.title)).toEqual(course.modules.map((m) => m.title))

        const activities = await db.query<{ title: string; status: string; author: string; questions: number }>(
            `select a.title, a.status, a.created_by as author,
                    (select count(*)::int from public.questions q where q.activity_id = a.id) as questions
             from public.activities a where a.course_id = $1 order by a.position`,
            [row.id],
        )
        const expected = course.modules.flatMap((m) => m.activities)
        expect(activities.rows.map((a) => a.title)).toEqual(expected.map((a) => a.title))
        expect(activities.rows.map((a) => a.questions)).toEqual(expected.map((a) => a.questions?.length ?? 0))
        expect(activities.rows.every((a) => a.status === 'published' && a.author === teacher)).toBe(true)

        const unkeyed = await db.query(
            `select q.id from public.questions q join public.question_keys k on k.question_id = q.id
             where q.kind <> 'short_answer' and cardinality(k.correct_option_ids) = 0`,
        )
        expect(unkeyed.rows).toHaveLength(0)
        const prerequisites = await db.query(`select 1 from public.activity_prerequisites`)
        expect(prerequisites.rows).toHaveLength(expected.reduce((n, a) => n + (a.requires?.length ?? 0), 0))
    })

    it('is safe to run twice', async () => {
        await createUser(db, course.ownerEmail, 'teacher')
        await db.exec(SEED)
        await db.exec(SEED)
        expect((await db.query(`select 1 from public.courses`)).rows).toHaveLength(1)
    })

    it('students who join with the code see the lessons, but never the answer keys', async () => {
        await createUser(db, course.ownerEmail, 'teacher')
        await db.exec(SEED)
        const student = await createUser(db, 'student@school.test')
        const { id } = (
            await db.query<{ id: string }>(`select id from public.courses where join_code = $1`, [course.joinCode])
        ).rows[0]
        await db.query(`insert into public.course_enrollments (course_id, student_id) values ($1, $2)`, [id, student])

        const seen = await asUser(db, student, () =>
            db.query(`select 1 from public.activities where course_id = $1 and kind = 'lesson'`, [id]),
        )
        expect(seen.rows.length).toBe(
            course.modules.flatMap((m) => m.activities).filter((a) => a.kind === 'lesson').length,
        )
        const keys = await asUser(db, student, () => db.query(`select 1 from public.question_keys`))
        expect(keys.rows).toHaveLength(0)
    })
})
